_choice_boolean() {
    cat <<-'EOF'
	yes	Enable
	no	Disable
	EOF
}

_choice_check_inhibitors() {
    cat <<-'EOF'
	auto	Respect inhibitor locks for interactive invocations
	yes	Always respect inhibitor locks
	no	Ignore inhibitor locks
	EOF
}

_choice_host() {
    {
        if [[ -r $HOME/.ssh/config ]]; then
            awk 'tolower($1) == "host" { for (i = 2; i <= NF; i++) print $i }' "$HOME/.ssh/config"
        fi
        if [[ -r /etc/hosts ]]; then
            awk '$1 !~ /^#/ && NF > 1 { for (i = 2; i <= NF; i++) print $i }' /etc/hosts
        fi
    } | grep -vE '^$|^[*?!]'
}

_choice_kill_whom() {
    cat <<-'EOF'
	main	Main process of the unit only
	control	Control processes of the unit only
	cgroup	All processes in the unit's control group
	all	All processes of the unit
	EOF
}

