_choice_preset_mode() {
    _helper_systemctl --preset-mode=help 2>/dev/null
}

_choice_property() {
    local unit=${argc__positionals[1]:-}
    if [[ $unit == -* ]]; then
        unit=
    fi
    _helper_systemctl show --all --no-pager ${unit:+"$unit"} 2>/dev/null |
        sed -n 's/^\([A-Za-z][A-Za-z0-9_]*\)=.*/\1/p'
}

_choice_signal() {
    _helper_systemctl --signal=help 2>/dev/null
}

_choice_state() {
    _helper_systemctl --state=help 2>/dev/null | sed '/:$/d; /^$/d'
}

_choice_timestamp() {
    _helper_systemctl --timestamp=help 2>/dev/null
}

_choice_type() {
    _helper_systemctl --type=help 2>/dev/null | sed '/:$/d; /^$/d'
}

_choice_unit() {
    _argc_util_parallel _helper_unit_loaded ::: _helper_unit_file
}

_choice_what() {
    _helper_systemctl --what=help 2>/dev/null
}

# Query the manager addressed by the manager-selecting options on the line.
# An option whose variable is declared but still empty (the word currently
# being completed) is not forwarded: `--machine=` would be rejected.
_helper_systemctl() {
    local opts=() option var
    for option in --user --host --machine --root --image; do
        var="argc_${option#--}"
        var=${var//-/_}
        if [[ -n ${!var:-} ]]; then
            opts+=($(_argc_util_param_select_options "$option"))
        fi
    done
    systemctl "${opts[@]}" "$@"
}

_helper_unit_file() {
    _helper_systemctl list-unit-files --no-legend --no-pager --output=json 2>/dev/null |
        jq -b -r '.[].unit_file'
}

_helper_unit_loaded() {
    _helper_systemctl list-units --all --no-legend --no-pager --plain --output=json 2>/dev/null |
        jq -b -r '.[] | select(.load != "not-found") | "\(.unit)\t\(.description)"'
}

_helper_unit_target() {
    _helper_systemctl list-units --type=target --all --no-legend --no-pager --plain --output=json 2>/dev/null |
        jq -b -r '.[] | "\(.unit)\t\(.description)"'
}
